def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, out) in enumerate(zip(inputs, outputs)):
        if inp != out:
            changed.append((i, inp, out))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit needed to transform s_in to s_out."""
    # Simple implementation for now - just return first difference
    min_len = min(len(s_in), len(s_out))

    # Find first position where they differ
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Check if we're replacing or inserting/deleting
            if len(s_in) == len(s_out):
                # Same length - replacement
                return (s_in[i], s_out[i], i)
            elif len(s_in) > len(s_out):
                # Deletion
                return (s_in[i], "", i)
            else:
                # Insertion
                return ("", s_out[i], i)

    # If we got here, one string is prefix of other
    if len(s_in) > len(s_out):
        return (s_in[min_len], "", min_len)
    elif len(s_in) < len(s_out):
        return ("", s_out[min_len], min_len)
    else:
        return ("", "", -1)  # No difference

